package com.example.expenses;

import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import org.springframework.boot.web.client.ClientHttpRequestFactories;
import org.springframework.boot.web.client.ClientHttpRequestFactorySettings;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

/** Calls GET /rates/{currency}; the body is expected as {"rate": 1.08}, the EUR value of one unit. */
@Component
public class ExchangeRateClient {
    private final RestClient client;

    public ExchangeRateClient(ExchangeRateProperties props) {
        var settings = ClientHttpRequestFactorySettings.defaults()
                .withConnectTimeout(props.timeout()).withReadTimeout(props.timeout());
        this.client = RestClient.builder()
                .baseUrl(props.baseUrl())
                .requestFactory(ClientHttpRequestFactories.get(settings))
                .build();
    }

    public BigDecimal rateToEur(String currency) {
        try {
            JsonNode body = client.get().uri("/rates/{c}", currency).retrieve().body(JsonNode.class);
            if (body == null || !body.hasNonNull("rate") || !body.get("rate").isNumber()) {
                throw new ExchangeRateException("Invalid rate response for " + currency, null);
            }
            return body.get("rate").decimalValue();
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException("Exchange rate unavailable for " + currency, e);
        }
    }
}
